const page="<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#111310\"><meta name=\"description\" content=\"Ton identit\u00e9 Free Fire prend une nouvelle dimension. Profil public, carte 3D et export social.\"><link rel=\"manifest\" href=\"/manifest.webmanifest\"><link rel=\"icon\" href=\"/icon.svg\"><title>FF ScoutMetrics \u2022 Player identity</title><style>\n:root{--lime:#ccff00;--pink:#f58bd3;--blue:#91c8ff;--bg:#10120f;--muted:#a0a59b}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:#f6f7ef;font-family:Arial,Helvetica,sans-serif}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}button{cursor:pointer}button:disabled{opacity:.6;cursor:wait}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--pink);outline-offset:4px}.wrap{max-width:1320px;margin:auto;padding:0 5%}nav{height:94px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff20}.brand{display:flex;align-items:center;gap:10px;font-size:19px;font-weight:800;letter-spacing:-.6px}.logo{background:var(--lime);color:#111;padding:8px 10px;border-radius:10px;transform:rotate(-7deg);font-size:22px}.brand small{display:block;font-size:9px;color:var(--muted);letter-spacing:2px;margin-top:5px}.links{display:flex;gap:32px;font-size:13px;color:#bcc0b6}.pill{padding:13px 20px;border:1px solid #ffffff35;border-radius:40px;background:transparent;color:inherit;font-size:12px}.pill:hover{border-color:var(--lime)}.hero{display:grid;grid-template-columns:1.05fr 1fr;gap:24px;min-height:740px;align-items:center;position:relative;padding:56px 0 65px}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:700;color:var(--lime);display:flex;align-items:center;gap:9px}.dot{width:6px;height:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px var(--lime)}h1{font-size:clamp(58px,6.8vw,99px);line-height:.98;letter-spacing:-6px;margin:26px 0}h1 em{font-style:normal;color:var(--lime)}.hero p{color:#aeb3a7;font-size:16px;line-height:1.8;max-width:390px}.primary{border:0;background:var(--lime);color:#172000;padding:17px 22px;border-radius:12px;font-weight:700;display:inline-flex;align-items:center;gap:28px}.primary:hover{background:#e0ff68}.actions{display:flex;align-items:center;gap:22px;margin:28px 0}.textlink{font-size:12px;color:#d3d7cd;border:0;background:none}.meta{display:flex;gap:20px;font-size:10px;color:var(--muted);margin-top:27px}.meta b{color:#eef0e4}.scene{height:590px;position:relative;perspective:1100px;display:flex;align-items:center;justify-content:center}.orb{position:absolute;width:440px;height:440px;border:1px solid #caff0030;border-radius:50%;transform:rotateX(63deg);bottom:-60px;box-shadow:0 0 100px #caff000c}.glow{position:absolute;inset:20%;background:#caff00;opacity:.13;filter:blur(75px);border-radius:50%}.hero-card{width:330px;height:474px;background:#ffdf00;border:1px solid #ffffff44;border-radius:26px;transform:rotateY(-16deg) rotateZ(8deg);box-shadow:-22px 30px 0 #23281d,0 45px 75px #000;overflow:hidden;position:relative;animation:float 7s ease-in-out infinite}.hero-card img{width:100%;height:100%;object-fit:cover}.hero-card .card-head{position:absolute;top:16px;left:17px;color:#191d12;font-size:10px;font-weight:bold;background:#fff;padding:7px 11px;border-radius:15px}.hero-card .card-foot{position:absolute;bottom:0;background:linear-gradient(transparent,#12160fee);padding:50px 22px 22px;width:100%}.card-foot b{font-size:29px}.card-foot small{display:block;font-size:10px;letter-spacing:2px;color:var(--lime);margin-top:7px}.float-tag{position:absolute;border:1px solid #ffffff35;border-radius:14px;padding:15px 18px;box-shadow:0 20px 50px #0008;background:#242820;font-size:12px;z-index:2}.tag-a{left:-4px;top:110px;transform:rotate(-10deg);background:var(--pink);color:#171316}.tag-b{right:-7px;bottom:100px;transform:rotate(7deg);background:var(--blue);color:#11202b}.tag-c{right:18px;top:40px;font-size:10px;color:var(--lime)}.float-tag b{display:block;font-size:20px;margin-top:6px}.strip{display:flex;align-items:center;justify-content:space-around;gap:25px;border-top:1px solid #ffffff1c;border-bottom:1px solid #ffffff1c;padding:26px 0;color:#acb39d;font-size:12px;letter-spacing:3px}.strip span:nth-child(even){color:var(--lime);font-size:24px}.section{padding:90px 0}.section-top{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:35px}h2{font-size:clamp(34px,4vw,54px);letter-spacing:-2px;line-height:1.08;margin:16px 0}h2 span{color:var(--lime)}.section-top p{color:var(--muted);font-size:13px;line-height:1.8;max-width:300px}.lookup{border:1px solid #444a36;border-radius:25px;padding:32px;background:linear-gradient(115deg,#232a19,#171a15 70%);position:relative;overflow:hidden}.lookup:after{content:'\u2197';position:absolute;right:18px;top:-44px;font-size:200px;color:#ccff0006;pointer-events:none}.lookup form{display:grid;grid-template-columns:1fr 220px auto;gap:13px;position:relative;z-index:1}label{font-size:11px;color:#bfc7b3;display:block;margin-bottom:9px}input,select{width:100%;border:1px solid #ffffff30;border-radius:12px;background:#11160e;color:white;padding:16px;min-height:52px}select{appearance:auto}.lookup form button{align-self:end}.note{font-size:11px;line-height:1.8;color:#a6af9a;margin:18px 0 0}.demo{background:none;border:0;color:var(--lime);text-decoration:underline;padding:0}.status{margin-top:14px;font-size:13px;line-height:1.6;color:#f6c4ba;min-height:20px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-top:35px}.step{border-top:1px solid #ffffff28;padding-top:20px}.step small{color:var(--lime);font-size:10px}.step h3{font-size:18px}.step p{color:var(--muted);font-size:12px;line-height:1.8}.studio{display:grid;grid-template-columns:1.1fr .9fr;background:#ebece4;color:#172011;border-radius:30px;overflow:hidden;min-height:620px}.poster-stage{background:#dcded4;display:grid;place-items:center;padding:40px;perspective:1000px;overflow:hidden;position:relative}.poster-stage:before{content:'PLAYER\\A IDENTITY';white-space:pre;position:absolute;top:35px;left:30px;font-size:64px;line-height:.9;font-weight:900;color:#cbd0c0;letter-spacing:-4px}.poster{position:relative;width:min(100%,320px);aspect-ratio:4/5;border-radius:22px;overflow:hidden;background:#ffdf00;box-shadow:0 30px 35px #131d1529;transform-style:preserve-3d;transition:transform .15s}.poster img{width:100%;height:100%;object-fit:cover}.poster .info{position:absolute;bottom:0;left:0;right:0;padding:55px 22px 20px;background:linear-gradient(transparent,#151b12 40%);color:white}.poster h3{font-size:30px;letter-spacing:-1px;margin:6px 0}.poster .badge{position:absolute;top:16px;left:15px;background:#fff;color:#252b20;border-radius:15px;padding:7px 10px;font-size:9px}.poster .stats{display:flex;justify-content:space-between;border-top:1px solid #ffffff44;padding-top:14px;margin-top:13px}.stats span{font-size:9px;color:#b5bdab}.stats b{display:block;color:#fff;font-size:20px;margin-bottom:4px}.poster .uid{font-size:10px;color:#d0d6c5}.studio-controls{padding:48px 36px}.studio-controls .eyebrow{color:#5c731f}.studio-controls p{font-size:13px;line-height:1.8;color:#606956}.tabs{display:flex;border:1px solid #b6bfa8;border-radius:12px;padding:4px;margin:25px 0;gap:5px}.tabs button{flex:1;border:0;border-radius:9px;padding:13px 5px;background:none;color:#48533a;font-size:11px}.tabs button.active{background:#18230e;color:var(--lime)}.colors{display:flex;gap:10px;margin:18px 0}.swatch{width:32px;height:32px;border:3px solid transparent;border-radius:50%;background:var(--c)}.swatch.active{outline:2px solid #263819;outline-offset:2px}.studio-controls .primary{display:block;width:100%;margin-top:12px;text-align:center;background:#1b2712;color:#d2ff58}.secondary{display:block;width:100%;padding:15px;border:1px solid #aab49d;background:transparent;border-radius:12px;margin-top:10px;color:#283d14;font-size:12px}.upload{font-size:11px;color:#526640;text-decoration:underline;cursor:pointer;margin-top:16px}.upload input{display:none}.studio-controls .note{color:#68715e}.features{display:grid;grid-template-columns:1fr 1fr;gap:20px}.feature{padding:33px;border:1px solid #ffffff25;border-radius:22px;position:relative}.feature .num{font-size:11px;color:var(--lime)}.feature h3{font-size:27px;letter-spacing:-1px}.feature p{color:var(--muted);font-size:13px;line-height:1.8;max-width:360px}.feature .icon{position:absolute;right:30px;top:30px;color:var(--pink);font-size:36px}.faq details{border-top:1px solid #ffffff25;padding:22px 0}.faq summary{cursor:pointer;font-size:15px}.faq p{color:var(--muted);font-size:13px;line-height:1.8;max-width:800px}.end{background:var(--lime);color:#152009;padding:50px;border-radius:26px;display:flex;align-items:center;justify-content:space-between;gap:25px}.end h2{margin:0;max-width:600px}.end button{border-color:#233414;color:#17240e;white-space:nowrap}footer{display:flex;justify-content:space-between;padding:34px 0;gap:30px;color:var(--muted);font-size:10px;line-height:1.7}dialog{border:1px solid #465136;border-radius:24px;background:#1a2015;color:#fff;padding:28px;width:min(92vw,620px);max-height:88vh}dialog::backdrop{background:#000a;backdrop-filter:blur(8px)}.close{float:right;border:0;color:white;background:transparent;font-size:23px}.results-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:24px 0}.results-grid div{background:#ffffff09;padding:16px;border-radius:12px;font-size:11px;color:#b2bcaa}.results-grid b{display:block;font-size:19px;color:#fff;margin-top:7px;overflow-wrap:anywhere}.result-source{font-size:11px;line-height:1.8;color:#b4bea9}.spinner{display:inline-block;width:15px;height:15px;border:2px solid #ccff0033;border-top-color:var(--lime);border-radius:50%;animation:spin .8s linear infinite;margin-right:8px;vertical-align:middle}@keyframes spin{to{transform:rotate(360deg)}}@keyframes float{50%{transform:translateY(-16px) rotateY(-10deg) rotateZ(5deg)}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;scroll-behavior:auto!important;transition:none!important}.hero-card{transform:rotate(5deg)}}@media(max-width:800px){nav{height:77px}.links{display:none}.hero{grid-template-columns:1fr;gap:0;padding-top:40px}.hero h1{letter-spacing:-3px;max-width:600px}.hero p{max-width:500px}.scene{height:520px;max-width:500px;width:100%;margin:auto}.hero-card{width:290px;height:415px}.tag-a{left:0;top:80px}.tag-b{right:0;bottom:50px}.strip{font-size:9px;letter-spacing:1px;gap:8px}.section{padding:60px 0}.section-top{display:block}.lookup form{grid-template-columns:1fr 1fr}.lookup form button{grid-column:1/-1;justify-content:center}.lookup{padding:22px}.studio{grid-template-columns:1fr}.poster-stage{padding:50px 35px}.studio-controls{padding:30px}.steps{gap:20px}.features{grid-template-columns:1fr}.end{padding:30px;display:block}.end button{margin-top:24px}.meta{gap:12px;font-size:9px}.brand{font-size:16px}nav>.pill{padding:10px 12px;font-size:10px}footer{flex-direction:column;gap:8px}.section-top h2{letter-spacing:-1px}}@media(max-width:420px){.lookup form{grid-template-columns:1fr}.steps{grid-template-columns:1fr}.hero h1{font-size:61px}.tag-c{right:0}.float-tag{padding:12px}.float-tag b{font-size:16px}.actions{gap:14px}.primary{padding:16px}.scene{height:480px}.hero-card{width:265px;height:380px}}@media print{body{background:white}.wrap>*{display:none!important}#studio-section{display:block!important}#studio-section>.section-top,.studio-controls{display:none!important}.studio{display:block;background:white}.poster-stage{background:white}.poster{width:150mm;box-shadow:none;transform:none!important}.poster-stage:before{display:none}}\n</style></head><body><div class=\"wrap\"><nav><a class=\"brand\" href=\"#\"><span class=\"logo\">\u2197</span><span>scoutmetrics<small>FREE FIRE \u00b7 PLAYER IDENTITY</small></span></a><div class=\"links\"><a href=\"#analyser\">Analyser mon profil</a><a href=\"#studio-section\">Le studio</a><a href=\"#concept\">Comment \u00e7a marche</a></div><button class=\"pill install\">Installer l\u2019app \u2197</button></nav><main><section class=\"hero\"><div><div class=\"eyebrow\"><span class=\"dot\"></span> TON JEU. TON HISTOIRE. TON IDENTIT\u00c9.</div><h1>Plus qu\u2019un ID.<br>Une <em>signature.</em></h1><p>Transforme ton profil Free Fire en une carte qui te ressemble. Du lobby aux r\u00e9seaux, donne une autre dimension \u00e0 ton parcours.</p><div class=\"actions\"><a class=\"primary\" href=\"#analyser\">Cr\u00e9er ma player card <span>\u2197</span></a><button class=\"textlink demo-open\">Explorer la d\u00e9mo \u2197</button></div><div class=\"meta\"><span><b>01</b> Profil public</span><span><b>02</b> Carte interactive</span><span><b>03</b> Export social</span></div></div><div class=\"scene\" aria-label=\"Exemple illustratif de carte en perspective\"><div class=\"glow\"></div><div class=\"orb\"></div><div class=\"float-tag tag-c\">\u2733 BUILT FOR YOUR NEXT MOVE</div><div class=\"float-tag tag-a\">PLAYER CARD<b>Une autre dimension.</b></div><div class=\"hero-card\"><img src=\"/art.jpg\" alt=\"Illustration conceptuelle cybern\u00e9tique jaune et blanc fournie en r\u00e9f\u00e9rence\"><span class=\"card-head\">SCOUTMETRICS / CONCEPT ART</span><div class=\"card-foot\"><b>NOVA.01</b><small>PROFIL FICTIF \u00b7 \u00c9DITION D\u00c9MO</small></div></div><div class=\"float-tag tag-b\">TON PROFIL, PARTOUT.<b>3D \u2192 Social \u2197</b></div></div></section><div class=\"strip\"><span>FREE FIRE</span><span>\u2733</span><span>PLAYER IDENTITY</span><span>\u2733</span><span>MADE TO SHARE</span><span>\u2733</span><span>MADAGASCAR</span></div><section class=\"section\" id=\"analyser\"><div class=\"section-top\"><div><div class=\"eyebrow\">01 / CONNEXION AU PROFIL</div><h2>Tout commence<br>par <span>ton ID.</span></h2></div><p>Un identifiant, un serveur, et les informations publiques disponibles. Tu gardes le contr\u00f4le de ce que tu partages.</p></div><div class=\"lookup\"><form id=\"lookup\"><div><label for=\"uid\">ID DU JOUEUR FREE FIRE</label><input id=\"uid\" name=\"uid\" placeholder=\"Ex. : ton identifiant num\u00e9rique\" inputmode=\"numeric\" pattern=\"[0-9]{5,15}\" required maxlength=\"15\" autocomplete=\"off\"></div><div><label for=\"region\">SERVEUR DU COMPTE</label><select id=\"region\"><option value=\"sg\">SG / r\u00e9gion compatible</option><option value=\"ind\">Inde</option><option value=\"br\">Br\u00e9sil / Am\u00e9riques</option><option value=\"me\">Moyen-Orient</option><option value=\"eu\">Europe</option><option value=\"bd\">Bangladesh</option><option value=\"pk\">Pakistan</option></select></div><button class=\"primary\" id=\"analyze\">Analyser le profil \u2197</button></form><p class=\"note\">Aucun mot de passe Free Fire demand\u00e9. L\u2019UID ne prouve pas la propri\u00e9t\u00e9 du compte. <button class=\"demo demo-open\">Essayer avec un profil fictif</button></p><div class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\"></div></div><div class=\"steps\" id=\"concept\"><div class=\"step\"><small>01 \u2014 IDENTIFIER</small><h3>Entre dans le game.</h3><p>Renseigne ton vrai UID et le serveur du compte. Une r\u00e9gion g\u00e9ographique ne d\u00e9termine pas forc\u00e9ment ton serveur.</p></div><div class=\"step\"><small>02 \u2014 COMPOSER</small><h3>Fais-en ta signature.</h3><p>Consulte les champs disponibles, personnalise les couleurs et ajoute une image que tu as le droit d\u2019utiliser.</p></div><div class=\"step\"><small>03 \u2014 PARTAGER</small><h3>Sors du lobby.</h3><p>Explore ta carte en relief ou t\u00e9l\u00e9charge une image 1080 \u00d7 1350, pr\u00eate pour les r\u00e9seaux sociaux.</p></div></div></section><section class=\"section\" id=\"studio-section\"><div class=\"section-top\"><div><div class=\"eyebrow\">02 / PLAYER CARD STUDIO</div><h2>Ton profil.<br><span>Ton univers.</span></h2></div><p>Une carte qui bouge avec toi. Un format que tu peux emporter partout.</p></div><div class=\"studio\"><div class=\"poster-stage\"><article class=\"poster\" id=\"poster\"><img id=\"character\" src=\"/art.jpg\" alt=\"Illustration de d\u00e9monstration, pas le personnage r\u00e9el d\u2019un joueur\"><span class=\"badge\" id=\"sourceBadge\">D\u00c9MO \u00b7 PERSONNAGE ILLUSTRATIF</span><div class=\"info\"><div class=\"eyebrow\" style=\"font-size:9px\" id=\"cardRole\">PLAYER IDENTITY / CONCEPT</div><h3 id=\"cardName\">NOVA.01</h3><div class=\"uid\" id=\"cardUid\">UID FICTIF \u00b7 AUCUN COMPTE ASSOCI\u00c9</div><div class=\"stats\"><span><b id=\"cardLevel\">72</b>NIVEAU</span><span><b id=\"cardPoints\">3 240</b>POINTS BR</span><span><b id=\"cardLikes\">8 420</b>LIKES</span></div></div></article></div><div class=\"studio-controls\"><div class=\"eyebrow\">DU PROFIL \u00c0 LA SIGNATURE</div><h2 style=\"font-size:36px\">Choisis ta<br>dimension.</h2><p id=\"studioDescription\">Exemple fictif pour explorer le studio. Les chiffres et le personnage ne correspondent \u00e0 aucun joueur r\u00e9el.</p><div class=\"tabs\" role=\"group\" aria-label=\"Mode de carte\"><button class=\"active\" id=\"mode3d\" aria-pressed=\"true\">\u2197 Carte 3D</button><button id=\"modeSocial\" aria-pressed=\"false\">\u25a7 Format social</button></div><label style=\"color:#526640\">TA COULEUR SIGNATURE</label><div class=\"colors\"><button class=\"swatch active\" aria-label=\"Jaune\" aria-pressed=\"true\" data-color=\"#ffdf00\" style=\"--c:#ffdf00\"></button><button class=\"swatch\" aria-label=\"Rose\" aria-pressed=\"false\" data-color=\"#f58bd3\" style=\"--c:#f58bd3\"></button><button class=\"swatch\" aria-label=\"Bleu\" aria-pressed=\"false\" data-color=\"#91c8ff\" style=\"--c:#91c8ff\"></button><button class=\"swatch\" aria-label=\"Vert\" aria-pressed=\"false\" data-color=\"#ccff00\" style=\"--c:#ccff00\"></button></div><button class=\"primary\" id=\"export\">T\u00e9l\u00e9charger la carte PNG \u2197</button><button class=\"secondary\" id=\"pdf\">Imprimer / enregistrer en PDF</button><button class=\"secondary\" id=\"share\">Partager ma carte</button><label class=\"upload\">+ Ajouter mon image de personnage<input type=\"file\" id=\"upload\" accept=\"image/png,image/jpeg,image/webp\"></label><p class=\"note\">PNG 1080 \u00d7 1350 \u00b7 PDF via impression<br>Image locale : aucun envoi au serveur.<br>La carte 3D est un effet de perspective, pas un mod\u00e8le 3D du personnage.</p><p id=\"exportStatus\" role=\"status\" class=\"note\"></p></div></div></section><section class=\"section\"><div class=\"section-top\"><div><div class=\"eyebrow\">03 / PENS\u00c9 POUR LA SUITE</div><h2>Mobile aujourd\u2019hui.<br><span>Plus loin demain.</span></h2></div></div><div class=\"features\"><article class=\"feature\"><span class=\"num\">WEB \u2192 ANDROID</span><span class=\"icon\">\u2197</span><h3>Le studio dans ta poche.</h3><p>Interface tactile et installation web sur Android compatible. Le studio d\u00e9j\u00e0 charg\u00e9 reste accessible hors connexion ; la recherche d\u2019un vrai profil n\u00e9cessite internet.</p><button class=\"pill install\">Installer la version web</button></article><article class=\"feature\"><span class=\"num\">DONN\u00c9ES \u2192 CONFIANCE</span><span class=\"icon\">\u2733</span><h3>Chaque chiffre a sa source.</h3><p>Une donn\u00e9e manquante reste inconnue. Une donn\u00e9e import\u00e9e garde sa provenance. Un profil consult\u00e9 n\u2019est jamais pr\u00e9sent\u00e9 comme un compte dont tu as prouv\u00e9 la propri\u00e9t\u00e9.</p><a class=\"pill\" href=\"#faq\">Comprendre les donn\u00e9es \u2197</a></article></div></section><section class=\"section faq\" id=\"faq\"><div class=\"eyebrow\">LES R\u00c9PONSES, SANS FLOU.</div><h2>Avant de te lancer.</h2><details open><summary>Peut-on vraiment tout r\u00e9cup\u00e9rer avec un ID ?</summary><p>Non. Le connecteur vise uniquement les informations publiques fournies par une source compatible : pseudo, niveau, r\u00e9gion, points de classement, likes et guilde selon disponibilit\u00e9. E-mail, t\u00e9l\u00e9phone, mot de passe, messages et identit\u00e9 r\u00e9elle ne sont pas recherch\u00e9s. Un UID existant sur un serveur ne prouve pas que tu en es le propri\u00e9taire.</p></details><details><summary>La recherche r\u00e9elle fonctionne-t-elle d\u00e9j\u00e0 ?</summary><p>Le parcours et le connecteur serveur sont impl\u00e9ment\u00e9s. L\u2019import r\u00e9el reste d\u00e9sactiv\u00e9 tant qu\u2019une cl\u00e9 fournisseur et les droits d\u2019utilisation ne sont pas configur\u00e9s. Aucun chiffre fictif n\u2019est renvoy\u00e9 \u00e0 la place d\u2019une recherche r\u00e9elle. Le bouton d\u00e9mo ouvre un exemple explicitement fictif.</p></details><details><summary>Est-ce mon vrai personnage Free Fire ?</summary><p>L\u2019illustration initiale est une r\u00e9f\u00e9rence de design, pas ton \u00e9quipement. Tu peux importer une capture ou un d\u00e9tour\u00e9 autoris\u00e9. Les identifiants d\u2019\u00e9quipement d\u2019une API ne suffisent pas \u00e0 reconstruire automatiquement un personnage 3D fid\u00e8le.</p></details><details><summary>Est-ce une application APK ?</summary><p>Cette version est une application web installable lorsque le navigateur le permet. Aucun APK sign\u00e9 n\u2019est livr\u00e9 \u00e0 ce stade. Une version Android avec Capacitor est pr\u00e9vue pour les fonctionnalit\u00e9s natives futures.</p></details><details><summary>Que conserve cette version ?</summary><p>Aucun compte, annuaire ni profil public persistant. L\u2019image import\u00e9e reste dans ton navigateur. Le cache hors connexion conserve l\u2019interface, sans r\u00e9ponses de recherche. La recherche r\u00e9elle, apr\u00e8s activation, transmet UID et serveur au fournisseur indiqu\u00e9.</p></details></section><section class=\"end\"><h2>Ton prochain move<br>commence ici.</h2><a class=\"pill\" href=\"#analyser\">Cr\u00e9er ma signature \u2197</a></section></main><footer><span>\u2197 scoutmetrics \u2014 Une cr\u00e9ation ind\u00e9pendante pour les joueurs.</span><span>Prototype priv\u00e9 \u00b7 Non affili\u00e9 \u00e0 Garena \u00b7 Donn\u00e9es d\u00e9mo identifi\u00e9es<br>\u00a9 2026 FF ScoutMetrics</span></footer></div><dialog id=\"result\"><button class=\"close\" aria-label=\"Fermer\">\u00d7</button><div class=\"eyebrow\" id=\"resultLabel\">ANALYSE DU PROFIL</div><h2 id=\"resultName\" style=\"font-size:34px\">Profil</h2><div class=\"results-grid\" id=\"resultFields\"></div><p class=\"result-source\" id=\"resultSource\"></p><button class=\"primary\" id=\"useProfile\">Cr\u00e9er cette carte \u2197</button></dialog><dialog id=\"installDialog\"><button class=\"close\" aria-label=\"Fermer\">\u00d7</button><div class=\"eyebrow\">WEB APP / ANDROID</div><h2 style=\"font-size:32px\">Ton raccourci<br>vers le studio.</h2><p style=\"font-size:14px;line-height:1.8\">Sur Chrome Android : ouvre le menu \u22ee puis \u00ab Installer l\u2019application \u00bb ou \u00ab Ajouter \u00e0 l\u2019\u00e9cran d\u2019accueil \u00bb. L\u2019option d\u00e9pend du navigateur et de l\u2019acc\u00e8s priv\u00e9 au site.</p><p class=\"note\">Il s\u2019agit d\u2019une installation web. Aucun APK n\u2019est t\u00e9l\u00e9charg\u00e9. Les fonctions natives Android sont une prochaine \u00e9tape.</p></dialog><script src=\"/app.js\" defer></script></body></html>\n";
